-- EDU-AFRIKA Syllabus & Examination Topic Library
-- Seed content is an educational baseline outline, NOT a representation that every topic is
-- an officially approved or current syllabus item. Admins must verify source/version before
-- changing mapping status to official_source_verified.
begin;

alter table public.edu_subject_topics
  add column if not exists topic_description text not null default '',
  add column if not exists learning_outcomes jsonb not null default '[]'::jsonb,
  add column if not exists source_status text not null default 'draft',
  add column if not exists source_reference text not null default 'EDU-AFRIKA baseline topic outline; official syllabus alignment not yet verified',
  add column if not exists updated_at timestamptz not null default now();

do $$ begin
  if not exists (select 1 from pg_constraint where conname='edu_subject_topics_source_status_check') then
    alter table public.edu_subject_topics add constraint edu_subject_topics_source_status_check
      check (source_status in ('draft','reviewed','official_source_verified'));
  end if;
end $$;

create table if not exists public.edu_subject_topic_exam_map (
  id uuid primary key default gen_random_uuid(),
  topic_id uuid not null references public.edu_subject_topics(id) on delete cascade,
  subject_code text not null references public.edu_subjects(code) on delete cascade,
  exam_code text not null references public.edu_exam_types(code) on delete cascade,
  syllabus_year integer not null default 2026 check (syllabus_year between 2000 and 2100),
  is_active boolean not null default true,
  verification_status text not null default 'draft'
    check (verification_status in ('draft','reviewed','official_source_verified')),
  source_title text not null default '',
  source_url text not null default '',
  review_note text not null default '',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique(topic_id,exam_code,syllabus_year),
  check (verification_status <> 'official_source_verified' or length(btrim(source_url)) > 0)
);
create index if not exists edu_subject_topic_exam_map_destination_idx
  on public.edu_subject_topic_exam_map(exam_code,subject_code,is_active,syllabus_year);
create index if not exists edu_subject_topic_exam_map_topic_idx
  on public.edu_subject_topic_exam_map(topic_id,is_active);

alter table public.edu_subject_topic_exam_map enable row level security;
drop policy if exists edu_subject_topic_exam_map_admin_all on public.edu_subject_topic_exam_map;
create policy edu_subject_topic_exam_map_admin_all on public.edu_subject_topic_exam_map
  for all to authenticated using (public.is_admin()) with check (public.is_admin());
revoke all on public.edu_subject_topic_exam_map from anon,authenticated;
grant select,insert,update,delete on public.edu_subject_topic_exam_map to authenticated;
grant all on public.edu_subject_topic_exam_map to service_role;
grant select,insert,update,delete on public.edu_subject_topics to authenticated;
grant all on public.edu_subject_topics to service_role;
grant select on public.edu_exam_types, public.edu_subjects to service_role;

alter table public.edu_questions
  add column if not exists ai_syllabus_verification_status text,
  add column if not exists ai_syllabus_source_url text not null default '',
  add column if not exists ai_syllabus_mapping_id uuid references public.edu_subject_topic_exam_map(id) on delete set null;

do $$ begin
  if not exists (select 1 from pg_constraint where conname='edu_questions_ai_syllabus_verification_check') then
    alter table public.edu_questions add constraint edu_questions_ai_syllabus_verification_check
      check (ai_syllabus_verification_status is null or ai_syllabus_verification_status in ('draft','reviewed','official_source_verified'));
  end if;
end $$;

-- Seed all 40 currently active subjects with a broad baseline catalogue. ON CONFLICT DO NOTHING
