insert into public.edu_subject_topic_exam_map
  (topic_id,subject_code,exam_code,syllabus_year,is_active,verification_status,source_title,source_url,review_note)
select t.id,t.subject_code,e.exam_code,coalesce(t.syllabus_year,2026),true,'draft',
       case e.exam_code when 'JAMB' then 'JAMB Integrated Brochure and Syllabus System (IBASS)' when 'WAEC' then 'WAEC e-Learning subject catalogue' when 'NECO' then 'NECO Senior School Certificate Examination information' when 'ICAN' then 'ICAN Professional Examinations Syllabus 2026' when 'ACCA' then 'ACCA official syllabus and study guides' when 'CFA' then 'CFA Program curriculum' else '' end,
       case e.exam_code when 'JAMB' then 'https://eligibility.jamb.gov.ng/' when 'WAEC' then 'https://www.waeconline.org.ng/e-learning/' when 'NECO' then 'https://neco.gov.ng/exams' when 'ICAN' then 'https://icanig.org/ican/assets/docs/ICAN_SYLLABUS_2026_Final_Updated_NEW.pdf' when 'ACCA' then 'https://www.accaglobal.com/africa/en/student/exam-support-resources.html' when 'CFA' then 'https://www.cfainstitute.org/programs/cfa-program/curriculum' else '' end,
       'Initial subject/topic pairing only. Verify this exact subject and topic against the current official syllabus and the candidate level before marking reviewed or official-source-verified.'
from eligible e
join public.edu_exam_types ex on ex.code=e.exam_code and ex.is_active=true
join public.edu_subject_topics t on t.subject_code=e.subject_code and t.is_active=true
on conflict (topic_id,exam_code,syllabus_year) do nothing;

comment on table public.edu_subject_topic_exam_map is
  'Examination-specific mapping of subject topics. Seed mappings are draft until an administrator verifies the current official syllabus.';
comment on column public.edu_questions.ai_syllabus_verification_status is
  'Verification state of the topic-to-exam mapping used when the AI draft was generated.';

commit;
notify pgrst,'reload schema';
